namespace Allegiance.Core.Sim;

/// <summary>
/// A single native star as generated by <c>StarImage::SetCount</c>: a unit
/// direction (drawn at infinity, no translation/parallax) plus a scalar
/// brightness in [0,1] (native stores a greyscale
/// <c>Color(bright,bright,bright)</c>). Framework-neutral floats so the
/// module stays headless-testable.
/// </summary>
public readonly record struct NativeStar(float DirX, float DirY, float DirZ, float Brightness);

/// <summary>
/// Faithful ports of the three <b>pure</b> pieces of the native per-sector sky:
/// (1) the MSVC CRT <c>rand()</c> sequence the native star field seeds with,
/// (2) <c>StarImage::SetCount</c> star generation
/// (<c>effect/starimage.cpp:32-53</c>), and (3) the cluster planet-placement
/// math (<c>Igc/clusterIGC.cpp:44-57</c> with the <c>BytePercentage</c>
/// divisor 240, <c>_Utility/Utility.h:1307+</c>).
/// </summary>
public static class NativeSkyMath
{
    /// <summary>
    /// MSVC CRT <c>rand()</c> — a faithful port so the seeded star field
    /// matches native <b>exactly</b> (the native <c>StarImage</c> calls
    /// <c>srand(seed)</c> then walks <c>rand()</c>,
    /// <c>starimage.cpp:37</c>). MSVC <c>rand()</c> is an LCG:
    /// <c>next = next*214013 + 2531011</c> (32-bit wrap), returning
    /// <c>(next &gt;&gt; 16) &amp; 0x7fff</c>; <c>RAND_MAX = 0x7fff</c>.
    /// glibc's <c>rand()</c> is a different generator, so it would NOT match
    /// native — this is the CRT-specific algorithm on purpose.
    /// </summary>
    public static class MsCrtRand
    {
        public const int RandMax = 0x7fff;
        private static uint _next;

        public static void Srand(uint seed) => _next = seed;

        public static int Rand()
        {
            _next = _next * 214013u + 2531011u;
            return (int)((_next >> 16) & 0x7fff);
        }
    }

    private const float FltEpsilon = 1.19209290e-7f;

    /// <summary>
    /// <c>random(min,max)</c> (<c>zmath.h:114-120</c>):
    /// <c>((float)rand()/RAND_MAX)*(max*(1-EPS)-min)+min</c>, consuming one
    /// <see cref="MsCrtRand.Rand"/> step.
    /// </summary>
    private static float Random(float min, float max)
        => ((float)MsCrtRand.Rand() / MsCrtRand.RandMax)
           * (max * (1f - FltEpsilon) - min) + min;

    /// <summary>
    /// <c>Vector::RandomDirection</c> (<c>zlib/vector.cpp:37-46</c>): a uniform
    /// point on the unit sphere via
    /// <c>(cos(yaw)cosPitch, sin(yaw)cosPitch, sinPitch)</c> with
    /// <c>sinPitch=random(-1,1)</c>, <c>cosPitch=sqrt(1-sinPitch²)</c>,
    /// <c>yaw=random(0,2π)</c>.
    /// </summary>
    private static Vector3Unit RandomDirection()
    {
        float sinPitch = Random(-1f, 1f);
        float cosPitch = MathF.Sqrt(1f - sinPitch * sinPitch);
        float yaw = Random(0f, 2f * MathF.PI);
        return new Vector3Unit(
            MathF.Cos(yaw) * cosPitch,
            MathF.Sin(yaw) * cosPitch,
            sinPitch);
    }

    /// <summary>
    /// <c>StarImage::SetCount(seed, nStars)</c> (<c>starimage.cpp:32-53</c>):
    /// the star count is <c>nStars*4</c>, reseeded from <c>seed</c>, each star a
    /// unit <c>RandomDirection()</c> and a brightness <c>random(0.25,1)</c>.
    /// Deterministic for a given (seed, nStars) and byte-identical to native.
    /// </summary>
    public static NativeStar[] GenerateStars(uint seed, short nStars)
    {
        int count = nStars * 4;
        if (count < 0) count = 0;          // guard: a corrupt negative nStars
        var stars = new NativeStar[count];
        MsCrtRand.Srand(seed);
        for (int i = 0; i < count; i++)
        {
            var dir = RandomDirection();
            float bright = Random(0.25f, 1f);
            stars[i] = new NativeStar(dir.X, dir.Y, dir.Z, bright);
        }
        return stars;
    }

    /// <summary>
    /// The planet's unit direction in the cluster (<c>clusterIGC.cpp:44-57</c>):
    /// <c>sinLat = planetSinLatitude/240 − 0.5</c>,
    /// <c>cosLat = sqrt(1−sinLat²)</c>,
    /// <c>lon = (planetLongitude/240)·2π</c>,
    /// <c>position = (cos(lon)cosLat, sin(lon)cosLat, sinLat)</c>.
    /// The two angle fields are <c>BytePercentage</c> bytes (divisor 240,
    /// <c>Utility.h</c>); the raw bytes are passed in.
    /// </summary>
    public static Vector3Unit PlanetDirection(byte planetSinLatitude, byte planetLongitude)
    {
        const float divisor = 240f;
        float sinLat = planetSinLatitude / divisor - 0.5f;
        float cosLat = MathF.Sqrt(1f - sinLat * sinLat);
        float lon = planetLongitude / divisor * (2f * MathF.PI);
        return new Vector3Unit(
            MathF.Cos(lon) * cosLat,
            MathF.Sin(lon) * cosLat,
            sinLat);
    }

    /// <summary>
    /// Framework-neutral unit-vector holder (avoid pulling XNA/System.Numerics
    /// into the headless Core).
    /// </summary>
    public readonly record struct Vector3Unit(float X, float Y, float Z);
}
